import heapq
from bisect import bisect_right

def min_days_to_buy_microtransactions(n, m, k, offers):
    # Initialize variables
    days = [float('inf')] * (n + 1)
    pq = []

    # Process each offer
    for d, t in offers:
        heapq.heappush(pq, (d, t))

    # Function to get the last day we bought a microtransaction of type t
    def get_last_day(t):
        return days[t]

    # Function to update the last day we bought a microtransaction of type t
    def update_last_day(t, d):
        days[t] = d

    # Function to get the number of microtransactions of type t bought up to day d
    def get_cumulative_bought(t, d):
        i = bisect_right(pq, (d, t))
        count = 0
        while i > 0:
            _, t_ = pq[i - 1]
            if t_ == t:
                count += 1
                i -= 1
            else:
                break
        return count

    # Main loop to simulate the process
    current_day = 0
    while True:
        current_day += 1

        # Check if we have enough money to buy all microtransactions
        total_cost = 0
        for t in range(1, n + 1):
            if k[t - 1] > 0:
                last_day = get_last_day(t)
                if last_day < current_day:
                    total_cost += max(k[t - 1], get_cumulative_bought(t, current_day)) * 2
                else:
                    total_cost += max(k[t - 1], get_cumulative_bought(t, current_day)) * 1

        if total_cost <= current_day:
            return current_day

        # Update the last day we bought microtransactions
        for t in range(1, n + 1):
            if k[t - 1] > 0:
                last_day = get_last_day(t)
                if last_day < current_day:
                    update_last_day(t, current_day)

