    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    m = int(data[1])
    k = list(map(int, data[2:2+n]))
    offers = [(int(data[2+n+2*i])-1, int(data[2+n+2*i+1])) for i in range(m)]

    result = min_days_to_buy_microtransactions(n, m, k, offers)
    print(result)
